    if (n.equals("NN64")) return FNN64.make(num.longValue());
    if (n.equals("ZZ")) return FBigNum.make(num);
    return null;
}

/**
 * The value a function declared with the return type range answers, where
 * its body's value is v: a numeral converted where range fixes a type, as
 * a binding converts it, and refused there where it does not convert;
 * without a declared return type, its default.
 */
public static FValue atReturn(FType range, FValue v) {
    if (!hasNumeral(v)) return v;
    if (range != null && !range.typeMatch(v)) {
        FValue c = Coercions.coerce(range, v);
        if (c == null) {
            return error(errorMsg("Type mismatch returning ", v, " (type ", v.type(), ") at the declared return type ", range));
        }
        return c;
    }
    return plain(v);
}

/**
 * The arguments a generic call infers its static arguments from: each
 * numeral at its default, which walk's promotion joins into the
 * narrowest type into which every argument coerces (P-74).  Where the
 * numerals at the positions of one type parameter include one with a
        // "place" are environment-free, and instead they snag their
        // environments from self.
        // This might be wrong; what about the case where the surrounding
        // environment is the
        // instantiation of some generic? It seems like signatures etc will
        // depend on this.
        Evaluator eval = new Evaluator(buildEnvFromEnvAndParams(envForApplication(selfValue), args));
        // selfName() was rewritten to our special "$self", and
        // we don't care about shadowing here.
        eval.e.putValueRaw(selfName(), selfValue);
        FValue res = eval.eval(body);
        // a numeral converts at the declared return type, and is its default elsewhere
        if (!Numerals.hasNumeral(res)) return res;
        boolean declared = def instanceof FnDecl && ((FnDecl) def).getHeader().getReturnType().isSome();
        return Numerals.atReturn(declared ? getRange() : null, res);
    } else if (def instanceof Method) {
        return ((Method) def).applyMethod(selfValue, args);
    } else {
        return bug(errorMsg("MethodClosure ", this, " has neither body nor def instanceof Method"));

    }
}

public FValue applyMethod(FObject self) {
    return applyMethod(self, Collections.<FValue>emptyList());
}
